mapper.select:
SELECT t.work_order_no AS workOrderNo, t.tenant_code AS tenantCode, t.product_id AS productId, t.product_seq AS productSeq, t.product_code AS productCode, t.product_name AS productName, t.unit AS productUnit, t.work_order_num AS workOrderNum, t.work_order_num * pb2.product_number AS demandNum, t.plan_start_date AS planStartDate, t.plan_end_date AS planEndDate FROM ( SELECT w.work_order_no, MAX(w.plan_start_date) AS plan_start_date, MAX(w.plan_end_date) AS plan_end_date, SUM(w.work_order_num) AS work_order_num, w.tenant_code, pb.product_seq, mp.product_code, mp.product_name, mp.unit, mp.id AS product_id FROM micro_manufacture_work_order w LEFT JOIN micro_product_bom pb ON w.tenant_code = pb.tenant_code AND w.product_seq = pb.product_seq LEFT JOIN micro_product mp ON w.product_seq = mp.product_seq AND w.tenant_code = mp.tenant_code WHERE pb.bom_type = 'STANDARD' AND pb.parent_id = '0' AND w.plan_start_date >= #{condition.planStartDate} AND w.plan_start_date <= #{condition.planEndDate} AND w.work_order_status IN ('10', '20') GROUP BY w.work_order_no, pb.product_seq, w.tenant_code ) AS t LEFT JOIN micro_product_bom pb2 ON t.tenant_code = pb2.tenant_code AND t.product_seq = pb2.parent_product_seq
WHERE pb2.product_seq = #{condition.productSeq}
ORDER BY t.plan_start_date
